<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import CreateOpportunityModal from '../components/opportunities/CreateOpportunityModal.vue'
import OpportunityCard from '../components/opportunities/OpportunityCard.vue'
import { useCustomerStore } from '../stores/customer'
import { useOpportunityStore } from '../stores/opportunity'
import { useProjectStore } from '../stores/project'
import type { CreateOpportunityInput, OpportunityStage } from '../types/opportunity'
import { activeOpportunityStages, formatOpportunityCurrency, opportunityStageLabels } from '../utils/opportunity'
import { formatCustomerDate } from '../utils/customer'

const opportunityStore=useOpportunityStore();const customerStore=useCustomerStore();const projectStore=useProjectStore()
const { customerFilter, filteredLostOpportunities, pipelineTotal, ownerFilter, searchQuery, showLost, weightedPipeline, wonTotal }=storeToRefs(opportunityStore)
const modalOpen=ref(false);const createButton=ref<HTMLButtonElement|null>(null);const draggingId=ref<string|null>(null);const dragOverStage=ref<OpportunityStage|null>(null);const feedback=ref('');let timer:number|undefined
const customers=computed(()=>customerStore.customers);const members=computed(()=>projectStore.teamMembers)
function items(stage:OpportunityStage){return opportunityStore.getOpportunitiesByStage(stage)}
function stageValue(stage:OpportunityStage){return items(stage).reduce((sum,item)=>sum+item.value,0)}
function customerName(id:string){return customerStore.getCustomerById(id)?.companyName??'未知客戶'}
function ownerName(id:string){return projectStore.getMemberById(id)?.name??'未指派'}
function feedbackMessage(message:string){feedback.value=message;if(timer)window.clearTimeout(timer);timer=window.setTimeout(()=>feedback.value='',4000)}
function updateStage(id:string,stage:OpportunityStage){if(opportunityStore.updateOpportunityStage(id,stage))feedbackMessage(`商機階段已更新為${opportunityStageLabels[stage]}。`)}
function drop(stage:OpportunityStage){if(draggingId.value)updateStage(draggingId.value,stage);draggingId.value=null;dragOverStage.value=null}
function closeModal(){modalOpen.value=false;void nextTick(()=>createButton.value?.focus())}
function create(input:CreateOpportunityInput){const item=opportunityStore.createOpportunity(input);feedbackMessage(`已建立「${item.title}」。`);closeModal()}
watch(modalOpen,(open)=>document.body.classList.toggle('has-modal-open',open));onBeforeUnmount(()=>{document.body.classList.remove('has-modal-open');if(timer)window.clearTimeout(timer)})
</script>
<template>
  <div class="opportunities-view"><header class="opportunities-view__header"><div><p>TaskFlow CRM</p><h1>銷售機會</h1><span>集中管理商機、銷售階段與預估成交價值。</span></div><button ref="createButton" type="button" @click="modalOpen=true">＋ 新增商機</button></header>
  <section class="opportunities-summary" aria-label="Pipeline 統計"><dl><div><dt>Pipeline 總金額</dt><dd>{{ formatOpportunityCurrency(pipelineTotal) }}</dd></div><div><dt>加權 Pipeline</dt><dd>{{ formatOpportunityCurrency(weightedPipeline) }}</dd></div><div><dt>已成交</dt><dd>{{ formatOpportunityCurrency(wonTotal) }}</dd></div></dl></section>
  <section class="opportunities-toolbar" aria-label="商機篩選"><label>搜尋商機<input v-model="searchQuery" placeholder="搜尋商機名稱" /></label><label>客戶篩選<select v-model="customerFilter"><option value="all">所有客戶</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.companyName }}</option></select></label><label>負責人篩選<select v-model="ownerFilter"><option value="all">所有負責人</option><option v-for="member in members" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label class="opportunities-toolbar__toggle"><input v-model="showLost" type="checkbox" /> 顯示失敗商機</label><button type="button" @click="opportunityStore.clearFilters()">清除篩選</button></section>
  <div v-if="feedback" class="opportunities-view__toast" role="status" aria-live="polite" aria-atomic="true">{{ feedback }}</div>
  <div class="pipeline-scroll-hint"><section class="pipeline" aria-label="銷售 Pipeline"><div v-for="stage in activeOpportunityStages" :key="stage" class="pipeline__column" :class="{ 'pipeline__column--over': dragOverStage===stage }" @dragover.prevent="dragOverStage=stage" @dragleave="dragOverStage=null" @drop.prevent="drop(stage)"><header><div><h2>{{ opportunityStageLabels[stage] }}</h2><span>{{ items(stage).length }}</span></div><strong>{{ formatOpportunityCurrency(stageValue(stage)) }}</strong></header><div class="pipeline__cards"><OpportunityCard v-for="item in items(stage)" :key="item.id" :opportunity="item" :customer-name="customerName(item.customerId)" :owner-name="ownerName(item.ownerId)" :dragging="draggingId===item.id" @dragstart="draggingId=$event" @dragend="draggingId=null;dragOverStage=null" @stage-change="updateStage" /><p v-if="!items(stage).length">目前沒有商機。</p></div></div></section></div>
  <section v-if="showLost" class="lost-opportunities" aria-labelledby="lost-opportunities-title"><header><h2 id="lost-opportunities-title">失敗商機</h2><span>{{ filteredLostOpportunities.length }}</span></header><p v-if="!filteredLostOpportunities.length">目前沒有符合條件的失敗商機。</p><ul v-else><li v-for="item in filteredLostOpportunities" :key="item.id"><div><strong>{{ item.title }}</strong><span>{{ customerName(item.customerId) }} · {{ ownerName(item.ownerId) }}</span></div><div><span>{{ formatOpportunityCurrency(item.value) }}</span><time :datetime="item.expectedCloseDate">{{ formatCustomerDate(item.expectedCloseDate) }}</time><button type="button" @click="updateStage(item.id,'lead')">重新啟用</button></div></li></ul></section>
  <CreateOpportunityModal v-if="modalOpen" :customers="customers" :members="members" @close="closeModal" @create="create" /></div>
</template>
<style scoped>
.opportunities-view{display:grid;gap:var(--space-5)}.opportunities-view__header{align-items:flex-end;display:flex;gap:var(--space-5);justify-content:space-between;padding:var(--space-2) 0 var(--space-3)}.opportunities-view__header p,h1,.opportunities-view__header span{margin:0}.opportunities-view__header p{color:var(--color-accent-strong);font-size:.75rem;font-weight:750;letter-spacing:.1em;text-transform:uppercase}h1{color:var(--color-text);font-size:clamp(1.875rem,4vw,2.5rem);letter-spacing:-.045em;line-height:1.1;margin-top:var(--space-2)}.opportunities-view__header span{color:var(--color-text-secondary);display:block;font-size:.9375rem;line-height:1.65;margin-top:var(--space-3)}.opportunities-view__header>button{background:var(--color-accent);border:1px solid var(--color-accent);border-radius:var(--radius-md);color:white;font:inherit;font-weight:700;min-height:2.75rem;padding:0 var(--space-4)}.opportunities-summary,.opportunities-toolbar,.lost-opportunities{background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-lg);box-shadow:var(--shadow-sm)}.opportunities-summary{padding:var(--space-4) var(--space-5)}dl{display:grid;gap:var(--space-4);grid-template-columns:repeat(3,minmax(0,1fr));margin:0}dt{color:var(--color-text-muted);font-size:.75rem;font-weight:700}dd{color:var(--color-text);font-size:1.25rem;font-variant-numeric:tabular-nums;font-weight:750;margin:var(--space-1) 0 0}.opportunities-toolbar{align-items:end;display:grid;gap:var(--space-3);grid-template-columns:minmax(0,1.4fr) repeat(2,minmax(8rem,.7fr)) auto auto;padding:var(--space-4)}label{color:var(--color-text-secondary);display:grid;font-size:.75rem;font-weight:700;gap:var(--space-1)}input,select{background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-md);color:var(--color-text);font:inherit;min-height:2.5rem;padding:0 var(--space-3)}.opportunities-toolbar__toggle{align-items:center;border:1px solid transparent;border-radius:var(--radius-md);cursor:pointer;display:flex;gap:var(--space-2);min-height:2.75rem;padding:0 var(--space-2);white-space:nowrap}.opportunities-toolbar__toggle:hover{background:var(--color-surface-subtle)}.opportunities-toolbar__toggle:has(input:focus-visible){outline:3px solid #93c5fd;outline-offset:2px}.opportunities-toolbar__toggle input{height:1.125rem;min-height:auto;padding:0;width:1.125rem}.opportunities-toolbar>button,.lost-opportunities button{background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-md);color:var(--color-text-secondary);font:inherit;font-size:.8125rem;font-weight:700;min-height:2.5rem;padding:0 var(--space-3)}input:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #93c5fd;outline-offset:2px}.pipeline-scroll-hint{min-width:0;position:relative}.pipeline-scroll-hint::after{background:linear-gradient(90deg,transparent,var(--color-page-background));bottom:var(--space-2);content:"";pointer-events:none;position:absolute;right:0;top:0;width:2rem}.pipeline{display:grid;gap:var(--space-4);grid-template-columns:repeat(5,minmax(15rem,1fr));overflow-x:auto;padding-bottom:var(--space-2)}.pipeline__column{background:var(--color-surface-subtle);border:1px solid transparent;border-radius:var(--radius-lg);min-height:18rem;padding:var(--space-3);transition:border-color 160ms ease,background-color 160ms ease}.pipeline__column--over{background:var(--color-accent-soft);border-color:var(--color-accent)}.pipeline__column>header{border-bottom:1px solid var(--color-border);display:flex;gap:var(--space-2);justify-content:space-between;padding:var(--space-2) var(--space-1) var(--space-3)}.pipeline__column header div{align-items:center;display:flex;gap:var(--space-2)}h2{color:var(--color-text);font-size:.875rem;margin:0}.pipeline__column header span,.lost-opportunities header span{background:var(--color-surface);border:1px solid var(--color-border);border-radius:999px;color:var(--color-text-secondary);font-size:.6875rem;font-weight:750;padding:.2rem var(--space-2)}.pipeline__column header strong{color:var(--color-text-secondary);font-size:.75rem}.pipeline__cards{display:grid;gap:var(--space-3);padding-top:var(--space-3)}.pipeline__cards>p,.lost-opportunities>p{color:var(--color-text-muted);font-size:.8125rem;margin:var(--space-3) 0}.lost-opportunities{padding:var(--space-5)}.lost-opportunities header{align-items:center;display:flex;justify-content:space-between}.lost-opportunities ul{display:grid;gap:var(--space-2);list-style:none;margin:var(--space-4) 0 0;padding:0}.lost-opportunities li{align-items:center;border-top:1px solid var(--color-border);display:flex;gap:var(--space-3);justify-content:space-between;padding-top:var(--space-3)}.lost-opportunities li>div{display:grid;gap:var(--space-1)}.lost-opportunities li strong{color:var(--color-text);font-size:.875rem}.lost-opportunities li span,.lost-opportunities time{color:var(--color-text-muted);font-size:.75rem}.lost-opportunities li>div:last-child{align-items:end}.opportunities-view__toast{background:var(--color-text);border-radius:var(--radius-md);bottom:var(--space-5);box-shadow:var(--shadow-lg);color:white;font-size:.8125rem;max-width:min(24rem,calc(100vw - 2rem));padding:var(--space-3) var(--space-4);position:fixed;right:var(--space-5);z-index:30}@media(max-width:70rem){.opportunities-toolbar{grid-template-columns:repeat(2,minmax(0,1fr))}.pipeline{grid-template-columns:repeat(5,minmax(16rem,1fr))}}@media(max-width:44rem){.opportunities-view__header{align-items:flex-start;flex-direction:column}.opportunities-view__header>button{width:100%}dl{grid-template-columns:minmax(0,1fr)}.opportunities-toolbar{grid-template-columns:minmax(0,1fr)}.lost-opportunities li{align-items:flex-start;flex-direction:column}.lost-opportunities li>div:last-child{align-items:start}.opportunities-view__toast{bottom:var(--space-4);left:var(--space-4);right:var(--space-4)} }@media(prefers-reduced-motion:reduce){.pipeline__column{transition:none}}
</style>
